mapper.select:
SELECT id, slug, title, category_id, annotation, occasion, year, featured, status, sort
FROM lots
WHERE status = 'published' AND category_id = #{categoryId} AND id != #{excludeId}
ORDER BY sort
LIMIT #{limit}

SELECT id, lot_id, path_thumb, path_full, alt, caption, sort
FROM lot_images
WHERE id = #{id}

SELECT id, lot_id, path, poster_path, caption
FROM lot_videos
WHERE lot_id = #{lotId}
